  ('SHOW-01', 'bluff', 'knowledge', '', 3, '峨弄错', '峨弄错是位于中国西藏自治区那曲地区（现那曲市）的一座高原湖泊，面积约2.75平方公里，属于青藏高原。名字中的「错」在藏语地名中通常指湖泊。', null, '["湖泊", "俚语", "昆虫"]'::jsonb, true),
  ('GEO-NEW-01', 'bluff', 'knowledge', '', 2, '鬼见愁', '鬼见愁是北京香山主峰「香炉峰」的俗称，位于香山公园内。因通往山顶的山路较为陡峭，民间用「鬼见愁」形容攀登的艰难。', null, '["妖怪", "中草药", "山峰"]'::jsonb, true),
  ('GEO-NEW-02', 'bluff', 'knowledge', '', 2, '可可托海', '可可托海是中国新疆维吾尔自治区阿勒泰地区富蕴县的一个镇，并不是真正的海。这里有额尔齐斯河、峡谷和历史矿业遗址，也因可可托海风景区而闻名。', null, '["城镇", "海洋", "民间传说"]'::jsonb, true),
  ('FUN-01', 'bluff', 'knowledge', '', 1, '海兔子', '海兔子通常指海兔类海蛞蝓，是生活在海洋中的软体动物。它们头部的一对嗅角形似兔耳，因此被称作「海兔」。它们不是真正的兔子，而是与海螺等同属软体动物门。', null, '["神话生物", "海洋动物", "玩具"]'::jsonb, true),
  ('FUN-03', 'bluff', 'knowledge', '', 1, '喷瓜', '喷瓜是一种葫芦科植物。它的果实成熟时，内部会积累较高的压力。当果实脱离果柄时，会将里面的黏液和种子快速喷射出去，以此完成种子传播。', null, '["古代武器", "植物", "地方小吃"]'::jsonb, true),
  ('FUN-04', 'bluff', 'knowledge', '', 1, '玻璃蛙', '玻璃蛙是一类主要生活在中南美洲热带地区的小型蛙类。它们部分身体组织具有较高透明度，尤其是腹部皮肤，有些种类可以透过腹部看见心脏、消化器官等内部结构，因此得名。', null, '["科幻装置", "两栖动物", "玻璃工艺"]'::jsonb, true),
  ('FUN-05', 'bluff', 'knowledge', '', 2, '龙血树', '龙血树是某些龙血树属植物的俗称。这些植物的树干受到损伤后，部分种类能够分泌或形成红色树脂，看起来像鲜血，因此被称为龙血树。龙血树属中一些植物具有独特的伞状树冠。', null, '["神话传说", "植物", "矿物"]'::jsonb, true),
  ('FUN-06', 'bluff', 'knowledge', '', 1, '尸花', '尸花是对某些散发腐败气味的植物的俗称，其中最著名的是巨魔芋。巨魔芋开花时，会释放类似腐肉的强烈气味，以吸引苍蝇、甲虫等昆虫前来帮助传粉。', null, '["古代祭祀", "植物", "昆虫"]'::jsonb, true),
  ('FUN-08', 'bluff', 'knowledge', '', 2, '灯塔水母', '灯塔水母是一种体型很小的海洋水母，学名为 Turritopsis dohrnii。在某些条件下，成年水母能够通过细胞转分化等过程重新进入较早的生活史阶段，因此常被称为具有「返老还童」能力的水母。但这不代表它不会因捕食、疾病或其他原因死亡。', null, '["海洋动物", "航海工具", "光学现象"]'::jsonb, true),
  ('FUN-10', 'bluff', 'knowledge', '', 2, '蓝眼泪', '蓝眼泪是一种海洋生物荧光现象。在某些海域，当能够发出生物荧光的浮游生物大量出现时，海浪、脚步或船只造成的水体扰动会激发蓝色光芒，夜晚看起来像一片会发光的蓝色海水。', null, '["植物", "海洋现象", "宝石"]'::jsonb, true),
  ('FUN-11', 'bluff', 'knowledge', '', 2, '复活草', '复活草是对某些具有较强脱水耐受能力的植物的俗称。这些植物在长期干旱时会失去大量水分，有些还会蜷缩起来，看起来像已经枯死；但当重新获得水分后，可以恢复正常的生理活动，因此被称为复活草。', null, '["古代药方", "植物", "魔术道具"]'::jsonb, true),
  ('FIT-02', 'bluff', 'knowledge', '', 2, '保加利亚蹲', '保加利亚蹲通常指保加利亚分腿蹲，是一种以下肢力量和单腿稳定性为重点的训练动作。练习时将后脚放在身后的长凳等支撑物上，前腿承担大部分负荷，通过屈膝和髋关节运动完成下蹲，主要锻炼股四头肌和臀部肌肉。', null, '["军事训练", "健身动作", "传统舞蹈"]'::jsonb, true),
  ('FIT-06', 'bluff', 'knowledge', '', 2, '空心支撑', '空心支撑是一种体操和核心力量训练动作，英文叫 Hollow Body Hold。练习者仰卧，将肩部和双腿稍微抬离地面，收紧腹部并尽量保持下背部贴近地面，使身体形成浅浅的弧形。这种动作常用于训练核心稳定性和身体控制能力。', null, '["建筑结构", "体操训练", "呼吸技术"]'::jsonb, true),
  ('FIT-08', 'bluff', 'knowledge', '', 3, '离心收缩', '离心收缩是肌肉收缩的一种形式，指肌肉在产生张力的同时被外部负荷拉长。例如做哑铃弯举时，缓慢将哑铃放下，肱二头肌仍在持续用力控制动作，但肌肉长度逐渐增加，这就是离心收缩。', null, '["物理实验", "机械故障", "肌肉运动"]'::jsonb, true),
  ('PSY-01', 'bluff', 'knowledge', '', 2, '鸡尾酒会效应', '指人在多个声音同时存在的环境中，能够选择性地注意其中一个人的讲话，而忽略其他声音。例如在嘈杂的聚会上专心听朋友说话，却仍有可能注意到远处有人叫自己的名字。', null, '["酒精反应", "社交礼仪", "听觉注意"]'::jsonb, true),
  ('PSY-02', 'bluff', 'knowledge', '', 1, '舌尖现象', '一种明明知道某个词、名字或答案，却暂时想不起来的记忆现象。人会觉得答案就在嘴边，甚至记得其中几个音节，但无法完整说出来，过一段时间可能突然想起。', null, '["记忆提取", "语言疾病", "味觉异常"]'::jsonb, true),
  ('PSY-03', 'bluff', 'knowledge', '', 3, '睡眠者效应', '指某些说服性信息对人的影响可能随着时间推移而增加。例如一个人听到某个有说服力的观点，同时知道来源不太可信；过段时间后，他可能逐渐忘记对来源的怀疑，却仍记得观点，从而变得更容易接受它。这种效应有特定发生条件，并非所有信息都会如此。', null, '["态度变化", "睡眠障碍", "记忆疾病"]'::jsonb, true),
  ('PSY-06', 'bluff', 'knowledge', '', 2, '虚假共识效应', '指人们倾向于高估其他人与自己持有相同观点、习惯或偏好的比例。例如自己不喜欢某部电影，就觉得大多数人应该也不喜欢，但真实情况可能并非如此。', null, '["法律制度", "社会认知", "调查作弊"]'::jsonb, true),
  ('PSY-09', 'bluff', 'knowledge', '', 3, '自运动效应', '在黑暗环境中，原本静止的单个光点有时会被观察者感知为正在移动。这种视觉错觉被称为自运动效应，也曾用于研究群体判断和社会规范形成。', null, '["视觉错觉", "运动训练", "机械原理"]'::jsonb, true),
  ('ECO-03', 'bluff', 'knowledge', '', 3, '柠檬市场', '经济学中的经典概念，常用二手车市场说明。当卖家比买家更清楚商品质量时，买家担心买到劣质品，因而不愿支付高价，导致优质商品的卖家可能退出市场，使整体市场质量下降。英语中的 lemon 可以表示有缺陷的汽车。', null, '["水果贸易", "食品安全", "信息不对称"]'::jsonb, true),
  ('ECO-05', 'bluff', 'knowledge', '', 2, '心理账户', '人们会在心理上把钱划分成不同用途或来源的账户，进而用不同标准对待同样金额的钱。例如花掉意外收到的100元可能比花掉辛苦工作赚来的100元更容易，即使两笔钱的实际购买力完全一样。', null, '["心理治疗", "消费决策", "银行账户"]'::jsonb, true),
  ('ECO-06', 'bluff', 'knowledge', '', 2, '宜家效应', '指人们因为亲自动手参与制作或组装某件物品，而可能赋予它高于客观水平的价值。例如自己花时间拼装的家具，可能觉得比一件同等质量、直接买来的成品更值得珍惜。', null, '["家具设计", "行为经济学", "家居装修"]'::jsonb, true),
  ('HLAW-02', 'bluff', 'knowledge', '', 3, '官当', '中国古代官员的一种特殊刑罚制度。符合条件的官员犯下特定罪行时，可以依据官职品级折抵徒刑等刑罚。唐代的《唐律疏议》对官当的适用范围、折抵年限及官员后续任用作出了规定。', null, '["古代货币", "官员服饰", "刑罚折抵"]'::jsonb, true),
  ('HLAW-05', 'bluff', 'knowledge', '', 2, '亲亲相隐', '中国古代法律允许一定范围内的亲属，在特定案件中相互隐瞒犯罪事实而免受或减轻相关处罚。《唐律疏议》规定了同居亲属相互容隐的规则，但谋反、谋大逆、谋叛等重罪不适用。', null, '["亲属容隐", "婚姻禁忌", "祭祖礼仪"]'::jsonb, true),
  ('HLAW-06', 'bluff', 'knowledge', '', 3, '热审', '明清时期的一种司法审查制度，主要在炎热季节审理、清理部分在押案件，尤其涉及较轻的笞杖案件，以便符合条件的犯人及时获得处理，减少暑热期间长期羁押造成的问题。', null, '["夏季祭祀", "医药疗法", "司法复审"]'::jsonb, true),
  ('MIX-07', 'bluff', 'knowledge', '', 2, '流浪行星', '指不围绕恒星运行、独自在星际空间中运动的行星质量天体。它们可能曾属于某个行星系统，后来因引力相互作用被抛出，也可能通过其他机制形成。', null, '["天文学", "社会学", "科幻文学"]'::jsonb, true),
  ('MIX-08', 'bluff', 'knowledge', '', 2, '月虹', '一种由月光而不是直接太阳光形成的彩虹。当月光照射空气中的水滴时，光会经过折射、反射及色散形成虹。由于通常较暗，人眼有时难以辨别它的颜色。', null, '["宝石品种", "光学现象", "神话传说"]'::jsonb, true),
  ('ODD-101', 'bluff', 'knowledge', '', 3, '宇宙拿铁', '宇宙拿铁（Cosmic Latte）是研究人员为宇宙平均可见颜色起的名称。科学家分析大量星系的光谱，再将它们合成为人眼感知的颜色，结果得到一种近似奶油米白色的色调，而不是人们想象中的深蓝或纯黑。', null, '["天文学", "咖啡饮品", "艺术流派"]'::jsonb, true),
  ('ODD-103', 'bluff', 'knowledge', '', 2, '意大利面化', '一种真实的天体物理学术语，英文为 Spaghettification。当物体靠近黑洞等强引力天体时，不同部位所受到的引力差可能将它沿着一个方向逐渐拉长，同时在横向压缩，就像被拉成一根细长的意大利面。', null, '["艺术设计", "黑洞物理", "食品加工"]'::jsonb, true),
  ('HERB-01', 'bluff', 'knowledge', '', 2, '刘寄奴', '一种传统中药名称。刘寄奴与北刘寄奴是不同来源的药材，不能混为一谈。药名还流传着与南朝宋开国皇帝刘裕有关的故事，因为「寄奴」正是刘裕的小名。', null, '["古代官职", "中药材", "历史人物"]'::jsonb, true),
  ('HERB-02', 'bluff', 'knowledge', '', 2, '徐长卿', '一种真实的中药，通常以萝藦科植物徐长卿的干燥根及根茎作为药材。虽然名字像古代文人，但它确实是植物药材的名称。', null, '["历史官员", "古代诗人", "中药材"]'::jsonb, true),
  ('MISC-01', 'bluff', 'knowledge', '', 2, '洞穴爆米花', '洞穴爆米花是一种洞穴矿物沉积构造，也叫 Cave Popcorn。它们是洞壁上突起的一簇簇小球状矿物，形状像爆开的玉米花，通常以方解石等碳酸盐矿物为主，并不能食用。', null, '["动物卵", "地质构造", "膨化食品"]'::jsonb, true),
  ('MISC-06', 'bluff', 'knowledge', '', 2, '妖精闪电', '又称精灵闪电，英文 Sprites，是在强烈雷暴云上方高空中短暂出现的一类发光现象。它有时呈现红色，并形成类似水母或树枝的形状，与普通的云地闪电不同。', null, '["舞台特效", "雷电现象", "民间传说"]'::jsonb, true),
  ('ODD-202', 'bluff', 'knowledge', '', 3, '圣诞树染色法', '一种法医生物检材的显微染色方法。它能让精子细胞的不同结构呈现不同颜色，方便检验人员在显微镜下辨认。名称来自染色结果的色彩组合，与真正的圣诞树无关。', null, '["法医检验", "节日工艺", "植物育种"]'::jsonb, true),
  ('GAME-01', 'bluff', 'knowledge', '', 2, '死亡传送', '速通玩家故意让游戏角色死亡，利用复活点或检查点重新出现的机制，迅速抵达原本需要绕很远才能到达的位置。这种做法称为 Death Warp，死亡反而可能帮助玩家节省通关时间。', null, '["科幻技术", "游戏速通", "宗教传说"]'::jsonb, true),
  ('STORY-01', 'bluff', 'story', '', 1, '你做过最疯狂的一件事是什么？', null, null, null, true),
  ('STORY-02', 'bluff', 'story', '', 1, '你经历过最囧的一件事是什么？', null, null, null, true),
  ('STORY-04', 'bluff', 'story', '', 1, '你做过最冲动的一个决定是什么？', null, null, null, true),
  ('STORY-05', 'bluff', 'story', '', 2, '你经历过最不可思议的巧合是什么？', null, null, null, true),
  ('STORY-06', 'bluff', 'story', '', 2, '你做过最勇敢的一件事是什么？', null, null, null, true),
  ('STORY-08', 'bluff', 'story', '', 1, '你做过最幼稚的一件事是什么？', null, null, null, true),
  ('STORY-11', 'bluff', 'story', '', 2, '你经历过最离谱的一次约会是什么？', null, null, null, true),
