  ('1cc99b820685', 'bluff', 'knowledge', '', 1, '「惨绿少年」是什么意思？', '风度翩翩、有才华的青年', '出自唐代《幽闲鼓吹》，原指穿淡绿色衣服的少年，跟「惨」没关系。', '["少年风采", "寒门求学", "科举落榜"]'::jsonb, true),
  ('b5c4fd624c83', 'bluff', 'knowledge', '', 1, '「博士买驴」是什么意思？', '写文章或说话啰嗦半天，抓不住重点', '《颜氏家训》：一个博士买驴，写了三张契约，还没出现一个「驴」字。', '["以物易物", "措辞冗长", "因材施教"]'::jsonb, true),
  ('f4cb96729369', 'bluff', 'knowledge', '', 1, '「不刊之论」是什么意思？', '正确到不能改动的言论', '古代写在竹简上，写错了用刀削掉叫「刊」；「不刊」就是不用改。', '["禁书审查", "立论严谨", "口头传闻"]'::jsonb, true),
  ('4f1e4dfb1d0c', 'bluff', 'knowledge', '', 1, '「曾参杀人」是什么意思？', '谣言说的人多了，连最亲的人都会相信', '有个同名的人杀了人，有人连着三次跟曾参的母亲说「曾参杀人了」，她最后吓得翻墙逃走。', '["谣言惑众", "大义灭亲", "故意顶罪"]'::jsonb, true),
  ('c8f1f6e2323d', 'bluff', 'knowledge', '', 1, '「吴牛喘月」是什么意思？', '因为吃过亏，见到相似的东西就害怕', '吴地天热，水牛怕晒，看到月亮以为是太阳，就喘起气来。', '["因惧误判", "农事劳累", "观测天象"]'::jsonb, true),
  ('816841b58b24', 'bluff', 'knowledge', '', 1, '「蜀犬吠日」是什么意思？', '少见多怪', '四川多雾，很少出太阳，狗一见到太阳就叫。', '["少见多怪", "早起勤奋", "恃强欺弱"]'::jsonb, true),
  ('ee9f60881c2c', 'bluff', 'knowledge', '', 1, '「弹冠相庆」是什么意思？', '一个人当了官，他的同伙也互相庆祝、准备跟着做官（贬义）', '「弹冠」是掸掉帽子上的灰，准备戴上去做官。', '["同党升迁", "同窗高中", "卸任归乡"]'::jsonb, true),
  ('b2b5d67cfa89', 'bluff', 'knowledge', '', 1, '「牛骥同皂」是什么意思？', '好的坏的混在一起，不加区分', '「骥」是千里马，「皂」是喂牲口的槽：千里马和牛在一个槽里吃饭。', '["因才任职", "同舟共济", "良莠混杂"]'::jsonb, true),
  ('526044865062', 'bluff', 'knowledge', '', 1, '「尾生抱柱」是什么意思？', '死守约定、不知变通', '尾生和女子约在桥下见面，女子没来，河水涨了他也不走，抱着桥柱被淹死。', '["临危救人", "攀附权贵", "拘守约定"]'::jsonb, true),
  ('83a7f2561dd9', 'bluff', 'knowledge', '', 1, '「青蝇吊客」是什么意思？', '生前没有知己', '三国虞翻说自己死后只有苍蝇来吊唁。', '["遭人诬陷", "丧礼奢华", "缺少知己"]'::jsonb, true),
  ('f3deb1e90ef7', 'bluff', 'knowledge', '', 1, '「季常之癖」是什么意思？', '怕老婆', '宋代陈季常的妻子很凶，苏轼写诗笑他「忽闻河东狮子吼，拄杖落手心茫然」。', '["嗜酒", "爱马", "惧内"]'::jsonb, true),
  ('bfee688d672e', 'bluff', 'knowledge', '', 1, '「鼓盆而歌」是什么意思？', '妻子去世；也形容看透生死', '庄子的妻子死了，他不哭，反而敲着瓦盆唱歌。', '["看淡生死", "宴会助兴", "庆贺乔迁"]'::jsonb, true),
  ('84ffe370ea05', 'bluff', 'knowledge', '', 1, '「莼鲈之思」是什么意思？', '思念家乡', '晋朝张翰在洛阳做官，见秋风起，想起家乡的莼菜羹和鲈鱼，就辞官回家了。', '["思乡", "食材挑选", "推荐贤才"]'::jsonb, true),
  ('caf6e249b295', 'bluff', 'knowledge', '', 1, '「鲁鱼亥豕」是什么意思？', '书在传抄、印刷时把字弄错', '「鲁」和「鱼」、「亥」和「豕」字形相近，容易抄错。', '["时辰推算", "文字讹误", "饮食禁忌"]'::jsonb, true),
  ('6a69fbe02714', 'bluff', 'knowledge', '', 1, '「金龟换酒」是什么意思？', '形容豪爽好客、不拘小节', '贺知章初见李白，解下身上佩戴的金龟换酒请他喝。', '["借债度日", "豪爽待客", "贿求官职"]'::jsonb, true),
  ('f6b9a649681a', 'bluff', 'knowledge', '', 1, '「曲突徙薪」是什么意思？', '提前采取措施，防患于未然', '有人劝主人把直烟囱改成弯的、把柴搬远，主人不听，后来果然失火。', '["事先防备", "搬迁避税", "重修家业"]'::jsonb, true),
  ('08d179d86b8c', 'bluff', 'knowledge', '', 1, '「焚琴煮鹤」是什么意思？', '糟蹋美好的东西，大煞风景', '把琴当柴烧，把仙鹤煮了吃。', '["清修禁欲", "慈悲放生", "糟蹋雅物"]'::jsonb, true),
  ('5648f347a002', 'bluff', 'knowledge', '', 1, '「胶柱鼓瑟」是什么意思？', '死板，不知道变通', '把瑟上调音的柱子用胶粘死再弹，就没法调音了。', '["默契合奏", "技艺娴熟", "拘泥成法"]'::jsonb, true),
  ('c684b81a9ee8', 'bluff', 'knowledge', '', 1, '「齐大非偶」是什么意思？', '对方门第太高，不敢高攀（推辞婚事的话）', '齐国想把公主嫁给郑国太子，太子说齐国太强大，不是我的良配。', '["邦交破裂", "推辞婚配", "结义交友"]'::jsonb, true),
  ('5a7dc2361672', 'bluff', 'knowledge', '', 1, '「楚弓楚得」是什么意思？', '东西虽然丢了，但没落到外人手里', '楚王丢了弓，说「楚国人丢的，楚国人捡到，何必去找」。', '["技艺失传", "以弱胜强", "失物留在本方"]'::jsonb, true),
  ('6fc0428ddf7e', 'bluff', 'knowledge', '', 1, '「一狐之腋」是什么意思？', '珍贵的东西或难得的人才', '狐狸腋下的一小块白毛最珍贵，「千羊之皮，不如一狐之腋」。', '["浅薄的见识", "狡猾的计策", "难得的珍品"]'::jsonb, true),
  ('171b74d1867d', 'bluff', 'knowledge', '', 1, '「解衣推食」是什么意思？', '对人十分关怀照顾', '韩信说刘邦把自己的衣服给他穿、把自己的饭给他吃。', '["告老还乡", "关怀他人", "节制饮食"]'::jsonb, true),
  ('8f74546ac4e5', 'bluff', 'knowledge', '', 1, '「中流击楫」是什么意思？', '收复失地、奋发图强的决心', '东晋祖逖北伐，船到江心时敲着船桨发誓：不收复中原就不再渡江回来。', '["划舟竞速", "立誓图强", "泛舟赏景"]'::jsonb, true),
  ('bac7d0997585', 'bluff', 'knowledge', '', 1, '「沐猴而冠」是什么意思？', '徒有其表，讽刺人装模作样', '猴子洗了澡戴上帽子，看着像人，其实还是猴子。', '["返璞归真", "徒有外表", "尊师守礼"]'::jsonb, true),
  ('62a026744dc2', 'bluff', 'knowledge', '', 1, '「白云亲舍」是什么意思？', '思念远方的父母', '唐朝狄仁杰在外做官，登山望见白云，说「我的父母就住在那片云下面」。', '["避世独居", "牵挂双亲", "请客留宿"]'::jsonb, true),
  ('7571d457d631', 'bluff', 'knowledge', '', 1, '「断齑画粥」是什么意思？', '形容读书刻苦、生活清贫', '范仲淹年轻时煮一锅粥，冻住后划成四块，配着切碎的咸菜，分早晚吃。', '["清贫苦读", "施粥救济", "医食调理"]'::jsonb, true),
  ('d5c23021c67f', 'bluff', 'knowledge', '', 1, '「季布一诺」是什么意思？', '说话极有信用', '楚地有谚语：「得黄金百斤，不如得季布一诺」。', '["言而有信", "仓促定约", "迫于威势"]'::jsonb, true),
  ('f1a173b5c3e5', 'bluff', 'knowledge', '', 1, '「倒屣相迎」是什么意思？', '热情地迎接客人', '东汉蔡邕听说王粲来访，急着出门，把鞋都穿倒了。', '["拒绝来访", "热情待客", "仓促逃难"]'::jsonb, true),
  ('5feed23a197b', 'bluff', 'knowledge', '', 1, '「秋扇见捐」是什么意思？', '女子失宠、被抛弃', '汉代班婕妤失宠后写诗，把自己比作秋天被丢在一边的扇子。', '["慷慨捐赠", "节令换衣", "受到冷落"]'::jsonb, true),
  ('eb90b69a73a5', 'bluff', 'knowledge', '', 1, '「雪泥鸿爪」是什么意思？', '往事留下的一点痕迹', '苏轼的诗：人生就像飞鸿踩在雪地上留下的爪印，鸿飞走了，哪还记得东西。', '["往事遗痕", "迷路寻踪", "大雪阻行"]'::jsonb, true)
